    val MAP: Map<String, DuaText> = mapOf(
        "dua_eid_takbeer" to DuaText("ঈদৰ পথত তাকবীৰ", "আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ, আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ, আল্লাহৰ বাহিৰে কোনো ইলাহ নাই, আৰু আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ, আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ, আৰু সকলো প্ৰশংসা আল্লাহৰ বাবে।", "চন্দ্ৰ দৰ্শনৰ নিশাৰ পৰা ঈদ-উল-ফিতৰৰ প্ৰাৰ্থনালৈকে, বিশেষকৈ ঈদৰ খেলপথাৰলৈ যোৱাৰ পথত।", "কোৰাণৰ আদেশঃ'যাতে আপুনি গণনা সম্পূৰ্ণ কৰে আৰু আল্লাহৰ মহানতা ঘোষণা কৰে'(আল-বাকাৰাহ 2:185)। ইবন মাছুদে (আৰ. এ.) এই তাকবীৰটো কৈছিল।"),
        "dua_ahsin_aqibatana" to DuaText("সকলো ক্ষেত্ৰতে আমাৰ শেষটো ভাল কৰি তোলক", "হে আল্লাহ, সকলো ক্ষেত্ৰতে আমাৰ অৱসান ভাল কৰা, আৰু আমাক এই পৃথিৱীত অপমান আৰু পৰৱৰ্তী শাস্তিৰ পৰা ৰক্ষা কৰা।", "প্ৰতিটো বিষয়ত ভাল ফলাফলৰ বাবে।", "যিজনে এই দুআ কৰে আৰু বিচাৰ হোৱাৰ আগতে মৃত্যু হয় (বিচাৰৰ পৰা সুৰক্ষিত)।"),
        "dua_fadlika_wa_rahmatik" to DuaText("মই আপোনাৰ অনুৰাগ আৰু দয়া বিচাৰো", "হে আল্লাহ, মই তোমাৰ অনুগ্ৰহ আৰু দয়া বিচাৰো, কিয়নো তোমাৰ বাহিৰে আন কোনোৱে ইয়াৰ অধিকাৰী নহয়।", "যেতিয়া যোগান আৰু দয়া বিচাৰে।", "খাদ্য নথকাৰ সময়ত অতিথিসকলে নবী (ছাঃ)-ৰ ওচৰলৈ আহিছিল; তেওঁ এই দুআটো তৈয়াৰ কৰিছিল, আৰু তাৰ পিছত এটা উপহাৰ আহিছিল।"),
        "dua_allahu_akbar_kabira_2696" to DuaText("এজন বেদুইনক শিকোৱা শব্দসমূহ", "কেৱল আল্লাহৰ বাহিৰে কাৰো উপাসনা কৰাৰ অধিকাৰ নাই, কেৱল আল্লাহৰ, কোনো অংশীদাৰ নাই। আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ, প্ৰচুৰ পৰিমাণৰ প্ৰশংসা; আল্লাহৰ বাবে প্ৰচুৰ প্ৰশংসা; বিশ্বজগতৰ প্ৰভু আল্লাহৰ গৌৰৱ; আৰু সৰ্বশক্তিমান, জ্ঞানী আল্লাহৰ বাহিৰে কোনো শক্তি বা শক্তি নাই।", "ধিক্ৰ আৰু দুআৰ এক বিস্তৃত বাক্যাংশ-এজন বেদুইনক শিকোৱা হৈছিল।", "ইয়াৰ পিছত তেওঁক'আল্লাহুমাঘফিৰ লি ৱাৰহামনী ৱাহদিনী ৱাৰজুকনী \"ক'বলৈ শিকোৱা হৈছিল।"),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("মই আগতে আৰু পিছত যি পঠিয়াইছিলোঁ ক্ষমা কৰক", "হে আল্লাহ, মই আগতে আৰু পিছত কৰা পাপসমূহ, মই গোপনে কৰা পাপসমূহ আৰু মই মুকলিভাৱে কৰা পাপসমূহ, মোৰ বাৰ্ধকলাপসমূহ, আৰু মোৰ তুলনাত আপুনি যি ভাল জানে তাক ক্ষমা কৰক। আপুনিহে আগত আনে আৰু আপুনিহে প্ৰত্যাৱৰ্তন কৰে; আপোনাৰ বাহিৰে কোনো ঈশ্বৰ নাই।", "তাছাহুদ আৰু চালাৱাটৰ পিছত, ছালামৰ আগতে।", "প্ৰবক্তা ছলীহুল্লাহ আলীহ ৱাছলে প্ৰাৰ্থনাৰ শেষত তাছাহহুদ আৰু ছালামৰ মাজত এই পাঠ কৰিছিল।"),
        "dua_jiddi_wa_hazli" to DuaText("মোৰ গুৰুত্ব আৰু মোৰ ঠাট্টা ক্ষমা কৰক।", "হে আল্লাহ, মই গুৰুতৰভাৱে আৰু ঠাট্টা কৰি, ভুলকৈ আৰু ইচ্ছাকৃতভাৱে কৰা পাপবোৰ মোক ক্ষমা কৰা-আৰু এই সকলোবোৰ মোৰ ভিতৰত আছে।", "সকলো ধৰণৰ পাপৰ বাবে ক্ষমা, জ্ঞাত আৰু অজ্ঞাত।", "নবী (ছাঃ)-ৰ এক বিস্তৃত ইস্তিফৰ।"),
        "dua_rising_ruku_mil" to DuaText("ৰুকুৰ পিছত-স্বৰ্গবোৰ পূৰণ কৰাৰ প্ৰশংসা কৰক", "হে আমাৰ প্ৰভু, আকাশমণ্ডলক ভৰাই, পৃথিৱীক ভৰাই আৰু তাৰ পিছত আপুনি যি বিচাৰে তাক ভৰাই দিয়া সকলো প্রশংসা আপোনাৰ।", "ৰুকুৰ পৰা উঠাৰ পিছত,'ৰব্বনা লাকাল-হামদ'ৰ সৈতে।", "নবী ছলীহ আলীহ ৱাছলে ৰুকুৰ পৰা উঠি এই কথা কৈছিল।"),
        "dua_istiftah_kabira" to DuaText("আল্লাহ সৰ্বশ্ৰেষ্ঠ, প্ৰশংসাৰে পৰিপূৰ্ণ।", "আল্লাহ সৰ্বশ্ৰেষ্ঠ, মহান; প্ৰচুৰ প্ৰশংসা আল্লাহৰ বাবে; আৰু ৰাতিপুৱা-সন্ধিয়া আল্লাহৰ গৌৰৱ হ'ব।", "যেতিয়া প্ৰাৰ্থনা আৰম্ভ কৰা হয় (প্ৰাৰম্ভিক প্ৰশংসাৰ এটা ৰূপ)।", "নবী (ছাঃ)-এ কৈছিলঃ ইয়াৰ বাবে স্বৰ্গৰ দুৱাৰ মুকলি কৰা হৈছিল।"),
        "dua_q_ashku_bathhi" to DuaText("যাকুবৰ দুআ (আৰু আছ)-মই কেৱল আল্লাহৰ ওচৰত অভিযোগ কৰোঁ।", "মই মোৰ কষ্ট আৰু মোৰ দুখৰ বাবে কেৱল আল্লাহৰ ওচৰত অভিযোগ কৰোঁ।", "গভীৰ শোক আৰু বিচ্ছেদৰ মাজত।", "য়াকুবে (আৰ. এছ.) ইউছুফ (আৰ. এছ.) ৰ পৰা পৃথক হৈ থকাৰ সময়ত এই কথা কৈছিল।"),
        "dua_q_khayrun_hafiza" to DuaText("আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ ৰক্ষক।", "আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ ৰক্ষক, আৰু তেওঁ দয়ালুসকলৰ ভিতৰত সৰ্বাধিক দয়ালু।", "শিশু বা প্ৰিয়জনক ভ্ৰমণলৈ পঠিওৱাৰ সময়ত।", "ইয়াকব (আৰু) য়ে নিজৰ পুত্ৰক আল্লাহৰ হাতত সমৰ্পিত কৰি এই কথা কৈছিল।"),
        "dua_q_aqraba_rashada" to DuaText("মোৰ প্ৰভুৱে মোক সোঁফালৰ ওচৰলৈ লৈ যোৱাৰ পথ দেখুৱাব পাৰে।", "হয়তো মোৰ প্ৰভুৱে মোক ইয়াতকৈ বেছি সঠিক আচৰণৰ ওচৰত থকা দিশলৈ পথ দেখুৱাব।", "যেতিয়া কোনো বিষয়ত ভাল উপায় বিচাৰি আছে।", "নবী (ছাঃ)-ক পাহৰি যোৱাৰ পিছত এই কথা ক'বলৈ কোৱা হৈছিল।"),
        "dua_q_sawa_as_sabil" to DuaText("মুসাৰ দুআ (এ. এছ.)-মোক সঠিক পথলৈ পথ দেখুৱাওক", "হয়তো মোৰ প্ৰভুৱে মোক সঠিক পথত লৈ যাব।", "যেতিয়া নতুন যাত্ৰা বা অচিনাকি পথত ওলাই যায়।", "মূছা (এ. এছ.)-এ মাদিয়ানৰ ফালে ঘূৰি অহাৰ সময়তে এই কথা কৈছিল।"),
        "dua_q_not_among_wrongdoers" to DuaText("মোক অপৰাধ কৰা লোকসকলৰ মাজত ৰাখিব নালাগে", "হে মোৰ প্ৰভু, মোক অন্যায়কাৰী লোকসকলৰ মাজত ৰাখিবা।", "এটা দুআয়ে আল্লাহক অন্যায়কাৰীসকলৰ পৰা এজনক পৃথক ৰাখিবলৈ অনুৰোধ কৰে।", "এটা দুআয়ে আল্লাহক অন্যায়কাৰীসকলৰ পৰা এজনক পৃথক ৰাখিবলৈ অনুৰোধ কৰে।"),
        "dua_q_do_not_make_us_trial" to DuaText("আমাক বিচাৰ কৰি নলয়", "হে আমাৰ প্ৰভু, আমাক অবিশ্বাসীসকলৰ বাবে পৰীক্ষা নকৰিবা, আৰু হে আমাৰ প্ৰভু, আমাক ক্ষমা কৰা। নিঃসন্দেহ তুমি সৰ্বশক্তিমান, দৰ্শক।", "ইব্ৰাহিম (আৰু তেওঁৰ সঙ্গীসকলৰ দুআ।", "ইব্ৰাহিম (আৰু তেওঁৰ সঙ্গীসকলৰ দুআ।"),
        "dua_morning_witness" to DuaText("তৌহিদৰ ৰাতিপুৱাৰ সাক্ষী", "হে আল্লাহ, মই ৰাতিপুৱা প্ৰৱেশ কৰিছো, তোমাৰ সিংহাসন বাহকসকল, তোমাৰ দূতে আৰু তোমাৰ সকলো সৃষ্টিক আহ্বান কৰি সাক্ষ্যকৰণ কৰিবলৈ যে তুমি আল্লাহ, তোমাৰ বাহিৰে কোনো ইলাহ নাই, কেৱল তুমি, অংশীদাৰবিহীন, আৰু মুহাম্মাদ ছলীহুল্লাহ ছালম তোমাৰ দাস আৰু ৰাছুল।", "বৰ্ণনাটোত ৰাতিপুৱা চাৰিবাৰকৈ কোৱাৰ কথা উল্লেখ আছে।", "বৰ্ণনাটোত ৰাতিপুৱা চাৰিবাৰকৈ কোৱাৰ কথা উল্লেখ আছে।"),
        "dua_evening_witness" to DuaText("তাৱাহিদৰ সন্ধিয়াৰ সাক্ষী", "হে আল্লাহ, মই সন্ধিয়া প্ৰৱেশ কৰিছো, তোমাৰ সিংহাসন বাহকসকল, তোমাৰ দূতে আৰু তোমাৰ সকলো সৃষ্টিক আহ্বান কৰি সাক্ষ্যকৰণ কৰিবলৈ যে তুমি আল্লাহ, তোমাৰ বাহিৰে কোনো ইলাহ নাই, কেৱল তুমি, অংশীদাৰবিহীন, আৰু মুহাম্মাদ ছলীহুল্লাহ ৱাছলেম তোমাৰ দাস আৰু ৰাছুল।", "বৰ্ণনাটোত সন্ধিয়া চাৰিবাৰকৈ কোৱাৰ কথা উল্লেখ আছে।", "বৰ্ণনাটোত সন্ধিয়া চাৰিবাৰকৈ কোৱাৰ কথা উল্লেখ আছে।"),
        "dua_morning_blessing" to DuaText("আশীৰ্বাদৰ বাবে ৰাতিপুৱা ধন্যবাদ", "হে আল্লাহ, আজি ৰাতিপুৱা মই বা তোমাৰ সৃষ্টিৰ যিকোনো গোটে যি আশীৰ্বাদ লাভ কৰিছে সেয়া কেৱল তোমাৰ পৰাই, কোনো অংশীদাৰ অবিহনে; সেয়েহে সকলো প্রশংসা আৰু কৃতজ্ঞতা তোমাৰ।", "আল্লাহৰ আশীৰ্বাদৰ বাবে কৃতজ্ঞতাৰ ৰাতিপুৱাৰ দক্ৰ।", "আল্লাহৰ আশীৰ্বাদৰ বাবে কৃতজ্ঞতাৰ ৰাতিপুৱাৰ দক্ৰ।"),
        "dua_evening_blessing" to DuaText("আশীৰ্বাদৰ বাবে সন্ধিয়া ধন্যবাদ", "হে আল্লাহ, আজি সন্ধিয়া মই বা তোমাৰ সৃষ্টিৰ যিকোনো গোটে যি আশীৰ্বাদ লাভ কৰিছে সেয়া কেৱল তোমাৰ পৰাই, কোনো অংশীদাৰ অবিহনে; সেয়েহে সকলো প্রশংসা আৰু কৃতজ্ঞতা তোমাৰ।", "আল্লাহৰ আশীৰ্বাদৰ বাবে কৃতজ্ঞতাৰ সন্ধিয়াৰ দক্ৰ।", "আল্লাহৰ আশীৰ্বাদৰ বাবে কৃতজ্ঞতাৰ সন্ধিয়াৰ দক্ৰ।"),
    )
